SELECT workflow.*, ( SELECT COUNT(1) FROM ai_agent_resource_user_grant grant_record WHERE grant_record.resource_type = 'WORKFLOW' AND grant_record.resource_id = workflow.id ) AS access_user_count FROM ai_workflow_definition workflow
AND ( workflow.workflow_code LIKE CONCAT('%', #{keyword}, '%') OR workflow.workflow_name LIKE CONCAT('%', #{keyword}, '%') OR workflow.description LIKE CONCAT('%', #{keyword}, '%') )
AND workflow.publish_status = #{publishStatus}
AND workflow.enabled = #{enabled}
ORDER BY workflow.updated_at DESC

SELECT * FROM ai_workflow_definition
WHERE id = #{id}
FOR UPDATE
